1	// Acceptance test for the change request:
2	//   "Invoices should move through stages. First a draft. Then I send it. Then it gets paid. Keep a
3	//    record when I send one. Only let me take payment once it has been sent."
4	//
5	// An invoice moves through three stages: DRAFT → SENT → PAID. On a project's detail page each invoice
6	// shows its stage (invoice-status). While it is a DRAFT it offers a control to send it
7	// (invoice-send-<id>) and NO control to take payment — payment is only offered once it has been SENT
8	// (invoice-pay-<id>). Sending flips the stage to SENT, persists across a fresh load, and — because
9	// the request wants a record kept when one is sent — appends exactly one audit record
10	// `INVOICE_SENT id=<id> amount=<amount>` per send. A newly created invoice starts as a DRAFT.
11	//
12	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
13	// (auditLines()). Data is arranged via resetAndSeed (the app's /__test__ endpoint): `clients` honours
14	// { id, name, email }, `projects` honours { id, name, clientId } and `invoices` honours
15	// { id, amount, projectId, status }.
16	import { test, expect, type Page, type Locator } from '@playwright/test';
17	import { resetAndSeed } from '../support/seed';
18	import { auditLines } from '../support/audit';
19	
20	// Each stage's status cell is matched by the WORD that names the stage, case-insensitively, so the
21	// test binds to the MEANING and not one capitalisation ("Draft"/"DRAFT"/"draft" all count). The word
22	// boundaries keep the three stages distinct from one another.
23	const DRAFT = /\bdraft\b/i;
24	const SENT = /\bsent\b/i;
25	const PAID = /\bpaid\b/i;
26	
27	const invoiceRows = (page: Page) => page.locator('[data-testid^="invoice-row-"]');
28	const statusOf = (page: Page, id: number): Locator =>
29	  page.getByTestId(`invoice-row-${id}`).getByTestId('invoice-status');
30	
31	// The audit records. The amount may be written bare (100) or with scale (100.00), so accept an
32	// optional fractional part; everything else is matched exactly.
33	const sentRecord = (id: number, amount: number) =>
34	  new RegExp(`^INVOICE_SENT id=${id} amount=${amount}(\\.\\d+)?$`);
35	const paidRecord = (id: number, amount: number) =>
36	  new RegExp(`^INVOICE_PAID id=${id} amount=${amount}(\\.\\d+)?$`);
37	
38	const linesMatching = (re: RegExp): string[] => auditLines().filter((line) => re.test(line));
39	
40	test.describe('Invoices move through stages: draft → sent → paid', () => {
41	  test('a draft offers a send control but no payment control until it has been sent', async ({
42	    page,
43	  }) => {
44	    await resetAndSeed({
45	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
46	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
47	      invoices: [{ id: 1, amount: 100, projectId: 1, status: 'DRAFT' }],
48	    });
49	
50	    await page.goto('/projects/1');
51	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
52	
53	    // It starts as a draft: it offers a send control, and does NOT yet offer a way to take payment.
54	    await expect(statusOf(page, 1)).toHaveText(DRAFT);
55	    const send = page.getByTestId('invoice-send-1');
56	    await expect(send).toBeVisible();
57	    await expect(page.getByTestId('invoice-pay-1')).toHaveCount(0);
58	
59	    // Nothing has been recorded yet — reset clears the audit file, so the record below is proof the
60	    // send (not the seeding) wrote it.
61	    expect(auditLines()).toEqual([]);
62	
63	    await send.click();
64	
65	    // The stage is now SENT: the send control is gone (it has already been sent) and a payment
66	    // control is now offered.
67	    await expect(statusOf(page, 1)).toHaveText(SENT);
68	    await expect(statusOf(page, 1)).not.toHaveText(PAID);
69	    await expect(page.getByTestId('invoice-send-1')).toHaveCount(0);
70	    await expect(page.getByTestId('invoice-pay-1')).toBeVisible();
71	
72	    // Exactly one record was kept for this send, carrying the invoice's id and amount.
73	    expect(linesMatching(sentRecord(1, 100))).toHaveLength(1);
74	    expect(auditLines()).toHaveLength(1);
75	
76	    // The SENT stage is held by the server, not just the page: it survives a fresh load, still
77	    // offering payment and not a second send, and reloading does not record the send again.
78	    await page.reload();
79	    await expect(statusOf(page, 1)).toHaveText(SENT);
80	    await expect(page.getByTestId('invoice-send-1')).toHaveCount(0);
81	    await expect(page.getByTestId('invoice-pay-1')).toBeVisible();
82	    expect(linesMatching(sentRecord(1, 100))).toHaveLength(1);
83	    expect(auditLines()).toHaveLength(1);
84	  });
85	
86	  test('sending one invoice records it and leaves the others as drafts', async ({ page }) => {
87	    await resetAndSeed({
88	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
89	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
90	      invoices: [
91	        { id: 1, amount: 100, projectId: 1, status: 'DRAFT' },
92	        { id: 2, amount: 250, projectId: 1, status: 'DRAFT' },
93	      ],
94	    });
95	
96	    await page.goto('/projects/1');
97	    await expect(invoiceRows(page)).toHaveCount(2);
98	
