1	// Acceptance test for the change request:
2	//   "Let me narrow that list to one stage. For example only the ones I have sent."
3	//
4	// The all-invoices page (invoices-page), which lists every invoice from every project, gains a
5	// control (data-testid="invoice-status-filter") that narrows the one list down to a SINGLE stage.
6	// The invoices move through the stages draft → sent → paid, so choosing a stage leaves only the
7	// invoices at that stage — the request's worked example is "only the ones I have sent", i.e. choose
8	// SENT and only the sent invoices remain. Before a stage is chosen the list is unfiltered (every
9	// invoice shows). Choosing a different stage narrows to THAT stage, and returning to "all stages"
10	// brings every invoice back, so the filter is genuinely keyed on the chosen stage and not hardwired
11	// to one. Because a filter outlives a click (CLAUDE.md rule 4) the chosen stage lives in the URL and
12	// survives a fresh load.
13	//
14	// The contract for the control: it is a <select> on the invoices page with one option per stage
15	// (its label naming the stage: draft / sent / paid) plus a default "all stages" option carrying an
16	// empty value (no stage ⇒ unfiltered). The test chooses a stage by finding the option whose label
17	// NAMES that stage (case-insensitively) and selecting it by the option's own value, so it binds to
18	// the stage's MEANING, not the exact value or capitalisation the control uses internally — the same
19	// way the sibling specs match the invoice-status cell by the stage word.
20	//
21	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
22	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId } and
23	// `invoices` honours { id, amount, projectId, status }.
24	import { test, expect, type Page, type Locator } from '@playwright/test';
25	import { resetAndSeed } from '../support/seed';
26	
27	// Each stage matched by the WORD that names it, case-insensitively, so the test binds to the
28	// MEANING and not one capitalisation. Word boundaries keep the three stages distinct.
29	const DRAFT = /\bdraft\b/i;
30	const SENT = /\bsent\b/i;
31	const PAID = /\bpaid\b/i;
32	
33	const invoiceRows = (page: Page) => page.locator('[data-testid^="invoice-row-"]');
34	const statusOf = (page: Page, id: number): Locator =>
35	  page.getByTestId(`invoice-row-${id}`).getByTestId('invoice-status');
36	
37	// Two invoices at EACH stage, spread across every project, so narrowing to one stage must drop the
38	// other four rows — a filter that merely hid a single row, or one hardwired to one stage, could not
39	// reproduce these results. Project names are chosen so none is a substring of another.
40	const SEED = {
41	  clients: [
42	    { id: 1, name: 'Acme Corp', email: 'hello@acme.test' },
43	    { id: 2, name: 'Globex', email: 'contact@globex.test' },
44	  ],
45	  projects: [
46	    { id: 1, name: 'Website Redesign', clientId: 1 },
47	    { id: 2, name: 'Mobile App', clientId: 2 },
48	    { id: 3, name: 'Billing System', clientId: 1 },
49	  ],
50	  invoices: [
51	    { id: 1, amount: 100, projectId: 1, status: 'DRAFT' },
52	    { id: 2, amount: 250, projectId: 2, status: 'SENT' },
53	    { id: 3, amount: 500, projectId: 3, status: 'PAID' },
54	    { id: 4, amount: 750, projectId: 1, status: 'SENT' },
55	    { id: 5, amount: 300, projectId: 2, status: 'DRAFT' },
56	    { id: 6, amount: 900, projectId: 1, status: 'PAID' },
57	  ],
58	};
59	
60	const DRAFT_IDS = [1, 5];
61	const SENT_IDS = [2, 4];
62	const PAID_IDS = [3, 6];
63	const ALL_IDS = [1, 2, 3, 4, 5, 6];
64	
65	// The ids of the currently-rendered invoice rows, ascending (order is not what this feature is about).
66	async function visibleIds(page: Page): Promise<number[]> {
67	  return invoiceRows(page).evaluateAll((els) =>
68	    els
69	      .map((el) => Number(el.getAttribute('data-testid')!.replace('invoice-row-', '')))
70	      .sort((a, b) => a - b),
71	  );
72	}
73	
74	// Choose a stage in the filter. The option is found by the stage WORD in its label and selected by
75	// that option's own value, so the stage is pinned by meaning, not by an exact value/capitalisation.
76	async function chooseStage(page: Page, word: RegExp): Promise<void> {
77	  const filter = page.getByTestId('invoice-status-filter');
78	  await expect(filter).toBeVisible();
79	  const value = await filter
80	    .locator('option')
81	    .filter({ hasText: word })
82	    .first()
83	    .evaluate((el: HTMLOptionElement) => el.value);
84	  await filter.selectOption(value);
85	}
86	
87	// Return the filter to "all stages": the default option carries no stage, so it has an empty value
88	// (an empty value clears the URL key, leaving the list unfiltered).
89	async function chooseAllStages(page: Page): Promise<void> {
90	  await page.getByTestId('invoice-status-filter').selectOption('');
91	}
92	
93	// Reach the invoices page the way a user would — via its nav link — so the page's own URL is not pinned.
94	async function openAllInvoices(page: Page): Promise<void> {
95	  await page.goto('/');
96	  const nav = page.getByTestId('nav-invoices');
97	  await expect(nav).toBeVisible();
98	  await nav.click();
99	  await expect(page.getByTestId('invoices-page')).toBeVisible();
100	}
