102	test.describe('Narrow all invoices to one stage', () => {
103	  test('the invoices page offers a stage filter and lists every invoice before one is chosen', async ({
104	    page,
105	  }) => {
106	    await resetAndSeed(SEED);
107	
108	    await openAllInvoices(page);
109	
110	    // The new filter control is present on the page.
111	    await expect(page.getByTestId('invoice-status-filter')).toBeVisible();
112	
